genre_data = {}

with open('bookstore_orders.csv', mode='r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        genre = row['primary_item_genre']
        if not genre:
            genre = "Unknown"

        is_returned = row['return_requested'].strip().lower() == 'yes'
        refund_amount = float(row['refund_amount']) if row['refund_amount'] else 0.0

        if genre not in genre_data:
            genre_data[genre] = {
                'TotalOrders': 0,
                'ReturnedOrders': 0,
                'TotalRefund': 0.0
            }

        genre_data[genre]['TotalOrders'] += 1
        if is_returned:
            genre_data[genre]['ReturnedOrders'] += 1
        genre_data[genre]['TotalRefund'] += refund_amount

results = []
for genre, data in genre_data.items():
    return_rate = (data['ReturnedOrders'] / data['TotalOrders']) * 100
    results.append({
        'Genre': genre,
        'TotalOrders': data['TotalOrders'],
        'ReturnedOrders': data['ReturnedOrders'],
        'ReturnRatePct': round(return_rate, 2),
        'TotalRefund': round(data['TotalRefund'], 2)
    })

# Sort by ReturnRatePct descending, then TotalRefund descending
results.sort(key=lambda x: (x['ReturnRatePct'], x['TotalRefund']), reverse=True)

# Save to CSV
with open('genre-returns.csv', mode='w', encoding='utf-8', newline='') as f:
    writer = csv.DictWriter(f, fieldnames=['Genre', 'TotalOrders', 'ReturnedOrders', 'ReturnRatePct', 'TotalRefund'])
    writer.writeheader()
    for row in results:
        writer.writerow(row)

print("genre-returns.csv has been created successfully.")
