{"content": "import csv
from datetime import datetime

carrier_data = {}

with open('bookstore_orders.csv', mode='r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        # Filter for successfully delivered orders
        if row['fulfillment_status'] != 'Delivered':
            continue

        carrier = row['carrier_name']
        if not carrier:
            carrier = "Unknown"

        estimated_str = row['estimated_delivery_date']
        actual_str = row['actual_delivery_date']

        if not estimated_str or not actual_str:
            continue

        # Parse dates
        # Handling both date and datetime-like
        try:
            estimated_date = datetime.strptime(estimated_str, '%Y-%m-%d %H:%M:%S')
            actual_date = datetime.strptime(actual_str, '%Y-%m-%d %H:%M:%S')
        except ValueError:
            estimated_date = datetime.strptime(estimated_str, '%Y-%m-%d')
            actual_date = datetime.strptime(actual_str, '%Y-%m-%d')

        if carrier not in carrier_data:
            carrier_data[carrier] = {
                'TotalDelivered': 0,
                'OnTimeDelivered': 0
            }

        carrier_data[carrier]['TotalDelivered'] += 1
        if actual_date <= estimated_date:
            carrier_data[carrier]['OnTimeDelivered'] += 1

results = []
for carrier, data in carrier_data.items():
    otd_pct = (data['OnTimeDelivered'] / data['TotalDelivered']) * 100 if data['TotalDelivered'] > 0 else 0.0
    results.append({
        'CarrierName': carrier,
        'TotalDelivered': data['TotalDelivered'],
        'OnTimeDelivered': data['OnTimeDelivered'],
        'OnTimePct': round(otd_pct, 2)
    })

# Sort by OnTimePct descending
results.sort(key=lambda x: x['OnTimePct'], reverse=True)

# Save to CSV
with open('carrier-otd.csv', mode='w', encoding='utf-8', newline='') as f:
    writer = csv.DictWriter(f, fieldnames=['CarrierName', 'TotalDelivered', 'OnTimeDelivered', 'OnTimePct'])
    writer.writeheader()
    for row in results:
        writer.writerow(row)

print("carrier-otd.csv has been created successfully.")
