    var lastProcessingUiUpdateTime by remember { mutableLongStateOf(0L) }
    var lastMetadataUiUpdateTime by remember { mutableLongStateOf(0L) }
    var colorSaturation by remember { mutableFloatStateOf(1.0f) }
