    var lastMetadataUiUpdateTime by mutableLongStateOf(0L)
    var colorSaturation by mutableFloatStateOf(1.0f)
    var currentFlickerHz by mutableIntStateOf(0)
    var lockExposure by mutableStateOf(false)
    var isShowingRawPreview by mutableStateOf(false)
    var isComparisonEnabled by mutableStateOf(false)
    var highlightRecoveryEnabled by mutableStateOf(true)
    var logRange by mutableFloatStateOf(500.0f)
    var isComparisonMode by mutableStateOf(false)
    var flashMode by mutableStateOf(FlashMode.AUTO)

    var isRecording by mutableStateOf(false)
    var recordingStartTime by mutableLongStateOf(0L)
    var recordingDuration by mutableIntStateOf(0)
    var currentVideoFile by mutableStateOf<File?>(null)
    var isRecordingLocked by mutableStateOf(false)
    var lockDragOffset by mutableFloatStateOf(0f)
    val lockThreshold = 56.dp
    var rawPreviewSurface by mutableStateOf<Surface?>(null)

    fun updatePipelineSettings() {
        livePreview.setPipelineSettings(
            useSpatialDenoise, useFalseColor, highlightRecoveryEnabled
        )
    }

    fun takePhoto() {
        val shutterStart = System.currentTimeMillis()
        locationTracker.updateLocation()

        val metadata = CaptureMetadata(
            iso = 0,
            exposureTimeNs = 0,
            focalLength = sensorCapture.getFocalLength(),
            aperture = sensorCapture.getAperture(),
            location = locationTracker.getLastLocation()
        )

        livePreview.requestCapture({ byteBuffer, width, height, timestamp, readbackTime, iso, shutter, meta, recycler ->
            coroutineScope.launch {
                val finalMeta = meta?.copy(iso = iso, exposureTimeNs = shutter) ?: metadata.copy(iso = iso, exposureTimeNs = shutter)
                processCaptureInBackground(context, byteBuffer, width, height, timestamp, readbackTime, shutterStart, finalMeta)
                recycler()
            }
        }, metadata)
        // Note: original used captureExecutor
    }

    fun toggleVideo() {
        if (isRecording) {
            captureVideo.stopRecording()
            val droppedFrames = livePreview.stopVideoRecording()
            sensorCapture.setAwbLock(false)
            isRecording = false
            isRecordingLocked = false
            lockDragOffset = 0f

            if (isComparisonMode) {
                livePreview.setComparisonMode(isComparisonEnabled)
                isComparisonMode = false
            }

            if (droppedFrames > 0) {
                Toast.makeText(context, "Recording finished with $droppedFrames dropped frames", Toast.LENGTH_LONG).show()
            }

            currentVideoFile?.let { videoFile ->
                val loc = locationTracker.getLastLocation()
                coroutineScope.launch {
                    saveVideoToGallery(context, videoFile, loc)
                }
            }
            currentVideoFile = null
        } else {
            val prefix = if (isComparisonEnabled) "LATENT_COMP_" else "LATENT_VID_"
            currentVideoFile = File(
                context.getExternalFilesDir(null),
                "${prefix}${System.currentTimeMillis()}.mp4"
            )
            currentVideoFile?.let { videoFile ->
                if (isComparisonEnabled) {
                    isComparisonMode = true
                    livePreview.setComparisonMode(true)
                }
                livePreview.startVideoRecording(captureVideo, videoFile, locationTracker.getLastLocation())
                isRecording = true
                sensorCapture.setAwbLock(true)
                recordingStartTime = System.currentTimeMillis()

                coroutineScope.launch {
                    while (isRecording) {
                        recordingDuration = ((System.currentTimeMillis() - recordingStartTime) / 1000).toInt()
                        kotlinx.coroutines.delay(1000)
                    }
                }
            }
        }
    }
}

class MainActivity : ComponentActivity() {
    private val volumeKeyEventFlow = MutableSharedFlow<Int>(extraBufferCapacity = 1)

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        window.addFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)
        enableEdgeToEdge()
        setContent {
            LatentTheme {
                MainScreen(volumeKeyEventFlow)
            }
        }
    }

    override fun onKeyDown(keyCode: Int, event: KeyEvent?): Boolean {
        if (keyCode == KeyEvent.KEYCODE_VOLUME_UP || keyCode == KeyEvent.KEYCODE_VOLUME_DOWN) {
            volumeKeyEventFlow.tryEmit(keyCode)
            return true
        }
        return super.onKeyDown(keyCode, event)
    }

    fun getRecordingReceiver(): android.content.BroadcastReceiver = recordingReceiver

    private val recordingReceiver = object : android.content.BroadcastReceiver() {
        override fun onReceive(context: android.content.Context?, intent: android.content.Intent?) {
            if (intent?.action == "com.pixelary.latent.TOGGLE_VIDEO") {
                volumeKeyEventFlow.tryEmit(KeyEvent.KEYCODE_VOLUME_DOWN)
            }
        }
    }
}

@Composable
fun MainScreen(volumeKeyEventFlow: SharedFlow<Int>) {
    val context = LocalContext.current
    val coroutineScope = rememberCoroutineScope()

    val cameraProvider = remember { CameraProvider(context) }
    val sensorCapture = remember { SensorCapture(context) }
    val livePreview = remember { LivePreview(context) }
    val captureVideo = remember { CaptureVideo() }
    val perfOptimizer = remember { PerformanceOptimizer(context) }
    val locationTracker = remember { LocationTracker(context) }
    val glSurfaceView = remember { GLSurfaceView(context) }

    val vm = remember { 
        CameraViewModel(context, cameraProvider, sensorCapture, livePreview, captureVideo, perfOptimizer, locationTracker, coroutineScope) 
    }

    val launcher = rememberLauncherForActivityResult(
        ActivityResultContracts.RequestMultiplePermissions()
    ) { permissions ->
        vm.hasCameraPermission = permissions[Manifest.permission.CAMERA] == true &&
                              permissions[Manifest.permission.RECORD_AUDIO] == true &&
                              permissions[Manifest.permission.ACCESS_FINE_LOCATION] == true
    }

    LaunchedEffect(Unit) {
        if (!vm.hasCameraPermission) {
            launcher.launch(arrayOf(
                Manifest.permission.CAMERA,
                Manifest.permission.RECORD_AUDIO,
                Manifest.permission.ACCESS_FINE_LOCATION,
                Manifest.permission.ACCESS_COARSE_LOCATION
            ))
        }
    }

    val activeThreads = remember { mutableStateOf(intArrayOf(android.os.Process.myTid())) }

    LaunchedEffect(Unit) {
        livePreview.setOnFrameProcessedListener { timeMs ->
            vm.processingTimeMs = timeMs
            vm.perfOptimizer.reportActualWorkDuration(timeMs * 1_000_000L)
            val now = System.currentTimeMillis()
            if (now - vm.lastProcessingUiUpdateTime > 500) {
                vm.processingTimeMs = timeMs
                vm.lastProcessingUiUpdateTime = now
            }
        }
        livePreview.setOnVideoThreadIdAvailableListener { tid ->
            if (!activeThreads.value.contains(tid)) {
                android.os.Process.setThreadPriority(tid, android.os.Process.THREAD_PRIORITY_URGENT_DISPLAY)
                activeThreads.value = activeThreads.value + tid
                vm.perfOptimizer.updateThreads(activeThreads.value)
            }
        }
        livePreview.setOnGlThreadIdAvailableListener { tid ->
            if (!activeThreads.value.contains(tid)) {
                android.os.Process.setThreadPriority(tid, android.os.Process.THREAD_PRIORITY_URGENT_DISPLAY)
                activeThreads.value = activeThreads.value + tid
                vm.perfOptimizer.updateThreads(activeThreads.value)
            }
        }
        livePreview.setOnIspThreadIdAvailableListener { tid ->
            if (!activeThreads.value.contains(tid)) {
                android.os.Process.setThreadPriority(tid, android.os.Process.THREAD_PRIORITY_URGENT_DISPLAY)
                activeThreads.value = activeThreads.value + tid
                vm.perfOptimizer.updateThreads(activeThreads.value)
            }
        }
        livePreview.setOnRawPreviewSurfaceReadyListener { surface ->
            vm.rawPreviewSurface = surface
        }
        livePreview.setRequestRenderCallback {
            glSurfaceView.requestRender()
        }
    }

    val captureExecutor = remember { Executors.newFixedThreadPool(2) }
    LaunchedEffect(captureExecutor) {
        val tids = mutableListOf<Int>()
        val count = 2
        val latch = java.util.concurrent.CountDownLatch(count)
        repeat(count) {
            captureExecutor.execute {
                val tid = android.os.Process.myTid()
                synchronized(tids) { tids.add(tid) }
                latch.countDown()
            }
        }
        withContext(kotlinx.coroutines.Dispatchers.IO) { latch.await() }
        if (tids.isNotEmpty()) {
            activeThreads.value = (activeThreads.value + tids).distinct().toIntArray()
            vm.perfOptimizer.updateThreads(activeThreads.value)
        }
    }
    DisposableEffect(Unit) {
        onDispose { captureExecutor.shutdown() }
    }

    LaunchedEffect(volumeKeyEventFlow) {
        volumeKeyEventFlow.collect { keyCode ->
            if (keyCode == KeyEvent.KEYCODE_VOLUME_UP) vm.takePhoto()
            else if (keyCode == KeyEvent.KEYCODE_VOLUME_DOWN) vm.toggleVideo()
        }
    }

    val lifecycleOwner = LocalLifecycleOwner.current
    DisposableEffect(lifecycleOwner) {
        val observer = LifecycleEventObserver { _, event ->
            if (event == Lifecycle.Event.ON_PAUSE || event == Lifecycle.Event.ON_STOP) {
                (context.findActivity() as? MainActivity)?.let {
                    try { context.unregisterReceiver(it.getRecordingReceiver()) } catch (e: Exception) {}
                }
                if (vm.isRecording) {
                    vm.captureVideo.stopRecording()
                    vm.livePreview.stopVideoRecording()
                    vm.isRecording = false
                    vm.currentVideoFile?.let { videoFile ->
                        val loc = vm.locationTracker.getLastLocation()
                        coroutineScope.launch { saveVideoToGallery(context, videoFile, loc) }
                    }
                    vm.currentVideoFile = null
                }
                vm.sensorCapture.closeCamera()
                vm.livePreview.clearPendingImage()
                vm.livePreview.cleanup()
                glSurfaceView.onPause()
                vm.selectedCameraId = ""
                vm.rawPreviewSurface = null
            } else if (event == Lifecycle.Event.ON_RESUME || event == Lifecycle.Event.ON_START) {
                (context.findActivity() as? MainActivity)?.let { activity ->
                    val filter = android.content.IntentFilter("com.pixelary.latent.TOGGLE_VIDEO")
                    ContextCompat.registerReceiver(context, activity.getRecordingReceiver(), filter, ContextCompat.RECEIVER_NOT_EXPORTED)
                }
                glSurfaceView.onResume()
                if (vm.rawPreviewSurface != null && (vm.selectedCameraId != "${vm.selectedCameraId}:${vm.selectedPhysicalId ?: ""}" || vm.rawPreviewSurface != vm.rawPreviewSurface)) {
                    vm.sensorCapture.closeCamera()
                    vm.livePreview.resetForCameraSwitch()
                    vm.sensorCapture.setOnSensorImageAvailableListener(object : SensorCapture.OnSensorImageAvailableListener {
                        override fun onSensorImageAvailable(reader: ImageReader) {
                            try {
                                val image = reader.acquireNextImage()
                                if (image != null) vm.livePreview.updateSensorImage(image)
                            } catch (e: Exception) {}
                        }
                    })
                    vm.sensorCapture.setOnMetadataAvailableListener(object : SensorCapture.OnMetadataAvailableListener {
                        override fun onMetadataAvailable(iso: Int, exposureTimeNs: Long, dynamicBlackLevel: FloatArray?, awbGains: FloatArray?, colorMatrix: FloatArray?, intrinsics: FloatArray?, flickerHz: Int) {
                            vm.livePreview.setIso(iso)
                            vm.livePreview.setExposureTime(exposureTimeNs)
                            if (flickerHz != vm.currentFlickerHz) {
                                vm.currentFlickerHz = flickerHz
                                if (flickerHz > 0 && vm.manualExposureTimeNs > 0) {
                                    val period = if (flickerHz == 50) 10_000_000L else 8_333_333L
                                    val snapped = Math.max(1L, Math.round(vm.manualExposureTimeNs.toDouble() / period) * period)
                                    if (snapped != vm.manualExposureTimeNs) {
                                        vm.manualExposureTimeNs = snapped
                                        vm.sensorCapture.setManualExposureTime(snapped)
                                    }
                                }
                            }
                            val now = System.currentTimeMillis()
                            if (now - vm.lastMetadataUiUpdateTime > 500) {
                                vm.currentIso = iso
                                vm.currentExposureTimeNs = exposureTimeNs
                                vm.lastMetadataUiUpdateTime = now
                            }
                            vm.livePreview.setBlackLevelPattern(dynamicBlackLevel ?: floatArrayOf(64f, 64f, 64f, 64f))
                            if (awbGains != null && !vm.isRecording) {
                                vm.livePreview.setWbGains(maxOf(0.1f, awbGains[0]), maxOf(0.1f, awbGains[1]), maxOf(0.1f, awbGains[2]))
                            }
                            if (colorMatrix != null) vm.livePreview.setColorMatrix(colorMatrix)
                        }
                    })
                    val effectiveId = vm.selectedPhysicalId ?: vm.selectedCameraId
                    val currentCameraInfo = vm.cameras.find { it.id == vm.selectedCameraId && (it.physicalId == vm.selectedPhysicalId || (it.physicalId == null && vm.selectedPhysicalId == null)) }
                    val isFront = currentCameraInfo?.facing == android.hardware.camera2.CameraCharacteristics.LENS_FACING_FRONT
                    vm.livePreview.setIsMirrored(isFront)
                    vm.livePreview.setSensorOrientation(vm.sensorCapture.getSensorOrientation(effectiveId))
                    vm.livePreview.setCfaPattern(vm.sensorCapture.getCfaPattern(effectiveId))
                    vm.livePreview.setBlackLevelPattern(vm.sensorCapture.getBlackLevelPattern(effectiveId))
                    vm.livePreview.setWhiteLevel(vm.sensorCapture.getWhiteLevel(effectiveId, vm.selectedCameraId).toFloat())
                    vm.livePreview.setDistortion(vm.sensorCapture.getLensDistortion(effectiveId))
                    vm.livePreview.setBlackLevelOffset(0.0f)
                    vm.livePreview.setAutoLevelsMode(vm.autoLevelsMode)
                    vm.livePreview.setShowHistogram(vm.showHistogram)
                    vm.livePreview.setLogRange(vm.logRange)
                    vm.livePreview.setPipelineSettings(vm.useSpatialDenoise, vm.useFalseColor, vm.highlightRecoveryEnabled)
                    currentCameraInfo?.maxPreviewResolution?.let { size -> vm.livePreview.setRawPreviewResolution(size.width, size.height) }
                    vm.sensorCapture.openCamera(vm.selectedCameraId, vm.selectedPhysicalId, vm.rawPreviewSurface)
                    vm.currentIsoRange = vm.sensorCapture.getIsoRange()
                    val rawShutterRange = vm.sensorCapture.getShutterRange()
                    vm.currentShutterRange = android.util.Range(rawShutterRange.lower, minOf(rawShutterRange.upper, 1_000_000_000L / 30))
                    vm.aeCompensationRange = vm.sensorCapture.getExposureCompensationRange()
                    vm.aeCompensationStep = vm.sensorCapture.getExposureCompensationStep()
                    vm.sensorCapture.setManualIso(vm.manualIso)
                    vm.sensorCapture.setManualExposureTime(vm.manualExposureTimeNs)
                    vm.sensorCapture.setExposureCompensation(vm.aeCompensation)
                    vm.sensorCapture.setAeLock(vm.lockExposure)
                    vm.sensorCapture.setUseOis(vm.useOis)
                    vm.perfOptimizer.enableSustainedPerformanceMode(context.findActivity()?.window ?: return@LaunchedEffect)
                    vm.perfOptimizer.startPerformanceSession(activeThreads.value)
                }
            }
        }
        val observer = LifecycleEventObserver { _, event -> /* event logic handled above */ }
        lifecycleOwner.lifecycle.addObserver(observer)
