{"content": "from PIL import Image
import numpy as np
import os

def get_ratio(path):
    img = Image.open(path).convert('RGB')
    data = np.array(img)
    green_channel = data[:,:,1]
    above = np.sum(green_channel > 128)
    below = np.sum(green_channel < 128)
    return above, below

def main():
    textures_dir = 'textures'
    for filename in os.listdir(textures_dir):
        path = os.path.join(textures_dir, filename)
        if not os.path.isfile(path) or not filename.endswith('.png'):
            continue
        try:
            above, below = get_ratio(path)
            print(f"{filename}: above={above}, below={below}")
        except Exception as e:
            print(f"Error processing {filename}: {e}")

if __name__ == "__main__":
    main()
